//  The built-in glyphs the collection icon picker offers. The full set is generated by
//  `scripts/generate-symbol-catalog.py`; a small inline set stands in when the resource is absent.

import Foundation

/// One catalog glyph: its SF Symbol name, its browse category and the extra search terms the picker
/// matches against.
public struct OPNCollectionSymbol: Hashable, Sendable {
    public let name: String
    public let category: String
    let keywords: [String]
}

/// One picker category.
public struct OPNCollectionSymbolCategory: Hashable, Sendable, Identifiable {
    public let id: String
    public let title: String
}

/// The symbol universe and the two queries the picker runs: by category, and by search text.
public enum OPNCollectionSymbolCatalog {
    public static let allCategoryID = "__opn_all_symbols__"
    /// The picker's opening chip: a hand-picked spread of recognizable glyphs, because "All" starts
    /// at the numeric and letter symbols and reads as noise before a search or a category is chosen.
    public static let popularCategoryID = "__opn_popular_symbols__"

    public static var symbols: [OPNCollectionSymbol] { catalog.symbols }
    public static var categories: [OPNCollectionSymbolCategory] { catalog.categories }

    private static let catalog = loadCatalog()
    private static let symbolsByCategory: [String: [OPNCollectionSymbol]] = Dictionary(grouping: catalog.symbols, by: \.category)
    private static let symbolsByName: [String: OPNCollectionSymbol] = Dictionary(
        catalog.symbols.map { ($0.name, $0) },
        uniquingKeysWith: { first, _ in first }
    )

    /// The curated spread the "Popular" chip draws, looked up against whichever catalog loaded so a
    /// name this platform does not carry is simply absent.
    public static let popular: [OPNCollectionSymbol] = popularNames.compactMap { symbolsByName[$0] }

    public static func symbols(in categoryID: String) -> [OPNCollectionSymbol] {
        switch categoryID {
        case popularCategoryID: return popular
        case allCategoryID: return symbols
        default: return symbolsByCategory[categoryID] ?? symbols
        }
    }

