    /// Every symbol matching each search term, best first. An empty query returns the category
    /// unchanged, so the picker can iterate the whole set without a second call shape.
    public static func search(_ query: String, categoryID: String) -> [OPNCollectionSymbol] {
        let terms = query
            .lowercased()
            .split(whereSeparator: { !$0.isLetter && !$0.isNumber })
            .map(String.init)
        let pool = symbols(in: categoryID)
        guard !terms.isEmpty else { return pool }
        return pool
            .compactMap { symbol -> (symbol: OPNCollectionSymbol, score: Int)? in
                let score = matchScore(symbol, terms: terms)
                return score < 0 ? nil : (symbol, score)
            }
            .sorted { $0.score == $1.score ? $0.symbol.name < $1.symbol.name : $0.score > $1.score }
            .map(\.symbol)
    }

    // MARK: - Matching

    private static func matchScore(_ symbol: OPNCollectionSymbol, terms: [String]) -> Int {
        let name = symbol.name.lowercased()
        let tokens = name.split(separator: ".").map(String.init)
        var total = 0
        for term in terms {
            if tokens.contains(term) {
                total += 100
            } else if tokens.contains(where: { $0.hasPrefix(term) }) {
                total += 60
            } else if symbol.keywords.contains(term) {
                total += 50
            } else if symbol.keywords.contains(where: { $0.hasPrefix(term) }) {
                total += 25
            } else if name.contains(term) {
                total += 30
            } else if symbol.category.contains(term) {
                total += 10
            } else {
                return -1
            }
        }
        return total
    }

    // MARK: - Loading

    private struct Catalog {
        var symbols: [OPNCollectionSymbol]
        var categories: [OPNCollectionSymbolCategory]
    }

    private struct FileRecord: Decodable {
        let categories: [FileCategory]
        let symbols: [FileSymbol]
    }

    private struct FileCategory: Decodable {
        let key: String
        let title: String
    }

    private struct FileSymbol: Decodable {
        let name: String
        let category: String
        let keywords: [String]
    }

    private static func loadCatalog() -> Catalog {
        decodeBundledCatalog() ?? fallbackCatalog
    }

    private static func decodeBundledCatalog() -> Catalog? {
        for subdirectory in ["Resources/CollectionIcons", "CollectionIcons", nil] as [String?] {
            guard let url = Bundle.main.url(forResource: "sf-symbols", withExtension: "json", subdirectory: subdirectory),
                  let data = try? Data(contentsOf: url),
                  let record = try? JSONDecoder().decode(FileRecord.self, from: data) else { continue }
            let symbols = record.symbols.map { OPNCollectionSymbol(name: $0.name, category: $0.category, keywords: $0.keywords) }
            let categories = record.categories.map { OPNCollectionSymbolCategory(id: $0.key, title: $0.title) }
            guard !symbols.isEmpty, !categories.isEmpty else { continue }
            return Catalog(symbols: symbols, categories: categories)
        }
        return nil
    }

    private static func entry(_ name: String, _ category: String) -> OPNCollectionSymbol {
        OPNCollectionSymbol(name: name, category: category, keywords: [])
    }

